    assignmentPattern.scope.push({ id: t.identifier("ref") });
    expect(program.toString()).toMatchInlineSnapshot(`
      "var ref;
      class C {
        m(a = f()) {}
      }"
    `);
    expect(program.scope.hasOwnBinding("ref")).toBe(true);
  });
});

