    const existingKind = existing.kind;

    const duplicate =
      // don't allow duplicate bindings to exist alongside
      kind === "let" ||
      existingKind === "let" ||
      existingKind === "const" ||
      existingKind === "module" ||
      // don't allow a local of param with a kind of let
      (existingKind === "param" && kind === "const");

    if (!duplicate) return;

    const scopeHub = localScope.path.hub;
    const pathHub = localPath.hub;
    const hub = scopeHub === pathHub ? scopeHub : scopeHub || pathHub;

    throw hub.buildError(
      id,
      `Duplicate declaration "${name}"`,
      TypeError,
    );
  }

